#Requires -Version 5.1
# fix-permisos-obras-asignar.ps1
#
# CAUSA EXACTA DEL PROBLEMA:
# obras/page.tsx y obras/[id]/page.tsx usaban "isAdmin" directamente
# en lugar de canDo("obras","crear"/"editar"/"eliminar").
# Pilar (rol Oficina, no admin) tenia los permisos correctos en BD
# pero la UI los ignoraba y solo mostraba botones a administradores.
#
# CAMBIOS:
# 1. obras/page.tsx: boton Nueva Obra y acciones usa puedeCrear/puedeEditar/puedeEliminar
# 2. obras/[id]/page.tsx: botones Editar/Eliminar/Archivar/Estado usan canDo
# 3. obras/[id]/obra-detail.tsx: importa canDo y usa puedeEditar
# 4. planificacion/page.tsx: puedeAsignar = canDo("planificacion","crear") [no "asignar"]
# 5. configuracion/page.tsx: columna "Asignar" eliminada de la matriz de permisos
# 6. usePermissions.ts: "asignar" eliminado del tipo y de la firma de canDo

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix permisos Obras + eliminar columna Asignar" -ForegroundColor Cyan

Write-Host "  -> src\app\obras\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\obras\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\obras\page.tsx"), $bytes)
Write-Host "  OK: 8 KB" -ForegroundColor Green

Write-Host "  -> src\app\obras\[id]\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\obras\[id]\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\obras\[id]\page.tsx"), $bytes)
Write-Host "  OK: 46 KB" -ForegroundColor Green

Write-Host "  -> src\app\obras\[id]\obra-detail.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\obras\[id]\obra-detail.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\obras\[id]\obra-detail.tsx"), $bytes)
Write-Host "  OK: 47 KB" -ForegroundColor Green

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\planificacion\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 72 KB" -ForegroundColor Green

Write-Host "  -> src\app\configuracion\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\configuracion\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\configuracion\page.tsx"), $bytes)
Write-Host "  OK: 27 KB" -ForegroundColor Green

Write-Host "  -> src\hooks\usePermissions.ts" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\hooks\usePermissions.ts")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\hooks\usePermissions.ts"), $bytes)
Write-Host "  OK: 3 KB" -ForegroundColor Green

$obras = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\obras\page.tsx"), [System.Text.Encoding]::UTF8)
$config = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\configuracion\page.tsx"), [System.Text.Encoding]::UTF8)
$hook = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\hooks\usePermissions.ts"), [System.Text.Encoding]::UTF8)
if ($obras.Contains("puedeCrear"))   { Write-Host "  OK: obras usa puedeCrear" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if (-not $config.Contains('"asignar"')) { Write-Host "  OK: asignar eliminado de configuracion" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if (-not $hook.Contains('"asignar"'))   { Write-Host "  OK: asignar eliminado de usePermissions" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "fix: permisos Obras por rol + eliminar permiso Asignar"'
Write-Host "  git push"
